package cn.minidayz.patcher;
import java.io.*;import java.security.*;import java.util.*;
/** Structural identity excluding only application label and manifest version values. */
public final class ManifestIdentity {
 static String string(List<String> strings,int i)throws Exception{if(i==-1)return "";BinaryManifest.require(i>=0&&i<strings.size());return strings.get(i);}
 public static String hash(byte[] xml)throws Exception{
  BinaryManifest.require(xml.length>=8&&BinaryManifest.u16(xml,0)==3&&BinaryManifest.i32(xml,4)==xml.length);List<String> strings=new ArrayList<String>();ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);boolean pool=false;int depth=0,version=0,code=0,label=0;
  for(int p=8;p<xml.length;){BinaryManifest.require(p<=xml.length-8);int type=BinaryManifest.u16(xml,p),header=BinaryManifest.u16(xml,p+2),size=BinaryManifest.i32(xml,p+4);BinaryManifest.require(header>=8&&size>=header&&size<=xml.length-p);
   if(type==1){BinaryManifest.require(!pool&&header>=28);pool=true;int count=BinaryManifest.i32(xml,p+8),styles=BinaryManifest.i32(xml,p+12),start=BinaryManifest.i32(xml,p+20);BinaryManifest.require(count>=0&&count<100000&&styles==0&&start>=header+count*4L&&start<size);boolean utf8=(BinaryManifest.i32(xml,p+16)&256)!=0;for(int i=0;i<count;i++){int[] at={p+start+BinaryManifest.i32(xml,p+header+4*i)};BinaryManifest.require(at[0]>=p+start&&at[0]<p+size);int chars=BinaryManifest.len(xml,at,utf8),length=utf8?BinaryManifest.len(xml,at,true):chars*2;BinaryManifest.require(length>=0&&at[0]<=p+size-length-(utf8?1:2));strings.add(new String(xml,at[0],length,utf8?"UTF-8":"UTF-16LE"));}}
   else if(type==0x180){BinaryManifest.require(pool&&header==8&&(size-8)%4==0);out.writeInt(type);out.writeInt((size-8)/4);for(int i=p+8;i<p+size;i+=4)out.writeInt(BinaryManifest.i32(xml,i));}
   else if(type==0x100||type==0x101||type==0x103){BinaryManifest.require(pool&&header==16&&size==24);out.writeInt(type);out.writeUTF(string(strings,BinaryManifest.i32(xml,p+16)));out.writeUTF(string(strings,BinaryManifest.i32(xml,p+20)));if(type==0x103)depth--;BinaryManifest.require(depth>=0);}
   else if(type==0x102){BinaryManifest.require(pool&&header==16&&size>=36);int h=p+header;String tag=string(strings,BinaryManifest.i32(xml,h+4));out.writeInt(type);out.writeUTF(string(strings,BinaryManifest.i32(xml,h)));out.writeUTF(tag);int base=h+BinaryManifest.u16(xml,h+8),stride=BinaryManifest.u16(xml,h+10),count=BinaryManifest.u16(xml,h+12);BinaryManifest.require(stride==20&&base==h+20&&base+(long)stride*count==p+size);out.writeInt(count);for(int i=0;i<3;i++)out.writeInt(BinaryManifest.u16(xml,h+14+2*i));Set<String> keys=new HashSet<String>();for(int i=0;i<count;i++){int a=base+i*stride;String ns=string(strings,BinaryManifest.i32(xml,a)),name=string(strings,BinaryManifest.i32(xml,a+4));BinaryManifest.require(keys.add(ns+"\u0000"+name));out.writeUTF(ns);out.writeUTF(name);int typ=xml[a+15]&255,value=BinaryManifest.i32(xml,a+16);BinaryManifest.require(BinaryManifest.u16(xml,a+12)==8&&xml[a+14]==0);boolean mutable=false;if(ns.equals("http://schemas.android.com/apk/res/android")){if(depth==0&&tag.equals("manifest")&&name.equals("versionName")){version++;mutable=true;}if(depth==0&&tag.equals("manifest")&&name.equals("versionCode")){code++;mutable=true;}if(depth==1&&tag.equals("application")&&name.equals("label")){label++;mutable=true;}}if(mutable){BinaryManifest.require(typ==3||typ==16||typ==1);out.writeInt(-1);}else{out.writeInt(typ);if(typ==3)out.writeUTF(string(strings,value));else out.writeInt(value);int raw=BinaryManifest.i32(xml,a+8);out.writeUTF(string(strings,raw));}}depth++;}
   else throw new IOException("E_MANIFEST_IDENTITY: 未知 XML 块，停止自动识别");p+=size;
  }BinaryManifest.require(depth==0&&version==1&&code==1&&label==1);out.close();return FilesEx.hex(MessageDigest.getInstance("SHA-256").digest(bytes.toByteArray()));
 }
}
